/**
 * Bundled Australian legal-term dictionary (research §7, "Terms KB").
 *
 * Australia has no equivalent of the Korean 법령용어 API, so the reference
 * server's terminology tools have no upstream to call. This table is the
 * substitute, and its rules follow from that:
 *
 *  - **`plain` and `legal` are descriptions, never quoted definitions.** No
 *    statutory text is reproduced or paraphrased as if it were the
 *    provision's own words. Where a term genuinely has a statutory meaning,
 *    the entry carries a *pointer* — `provisions` — and the caller fetches
 *    the real text with `get_term_provisions(includeText: true)` or
 *    `get_law_text`. That keeps a summary from hardening into a citation.
 *  - **`titleId` is only ever a Federal Register id already verified in
 *    `law-alias-data.ts`,** which is why it is looked up from that table
 *    rather than retyped. State and territory Acts are not on the Federal
 *    Register, so their entries carry a title and a pinpoint and no id: the
 *    text tools will decline to fetch rather than guess.
 *  - **A miss in this table is a miss in this table.** It is not evidence
 *    that a term is not a legal term; the KB tools say so in as many words.
 *
 * Pinpoints are the anchors practitioners cite. They can move when an Act is
 * amended, so every tool that prints one also prints the way to read the
 * current text.
 */

import { LAW_ALIAS_ENTRIES } from "./law-alias-data.js"

/** A statutory anchor for a term: where the meaning or the standard lives. */
export interface TermProvision {
  /** Full title as it should be cited, including the jurisdiction bracket. */
  title: string
  /** Federal Register id, present only for Commonwealth titles already verified. */
  titleId?: string
  /** Provision reference in the `section-ref` grammar: `s 18`, `sch 2 s 18`, `pt 2-3`. */
  ref: string
}

export interface LegalTermEntry {
  /** Canonical legal term, lower case unless it is a proper name. */
  term: string
  /** Plain-English meaning — what a non-lawyer needs to understand it. */
  plain: string
  /** How the term functions in law: elements, the test, the usual dispute. */
  legal?: string
  /** Statutory anchors, most-central first. */
  provisions?: TermProvision[]
  /** Related terms in this table. */
  seeAlso?: string[]
  /** Everyday phrasings that should resolve to this term ("sacked", "ripped off"). */
  plainAliases?: string[]
}

function idFor(alias: string): string | undefined {
  return LAW_ALIAS_ENTRIES.find((entry) => entry.alias === alias)?.titleId
}

/** Builder for a Commonwealth title whose register id is in the alias table. */
function act(alias: string, title: string): (ref: string) => TermProvision {
  const titleId = idFor(alias)
  return (ref) => ({ title, ...(titleId ? { titleId } : {}), ref })
}

/** Builder for a title with no verified register id (state, territory, unlisted). */
function untracked(title: string): (ref: string) => TermProvision {
  return (ref) => ({ title, ref })
}

const cca = act("CCA", "Competition and Consumer Act 2010 (Cth)")
/** The ACL is CCA schedule 2 — the schedule must stay in the ref (s 18 ≠ sch 2 s 18). */
const acl = (ref: string): TermProvision => {
  const built = cca(`sch 2 ${ref}`)
  return { ...built, title: "Competition and Consumer Act 2010 (Cth) sch 2 (Australian Consumer Law)" }
}
